// Determine whether the trailing backslash is escaped by counting the
// total number of trailing backslashes. An odd number means the last
// backslash is unescaped, which is not portable.
let trailing_backslashes = slice.iter().rev().take_while(|&&b| b == b'\\').count();

if trailing_backslashes % 2 == 1 {
    show!(USimpleError::new(
        0,
        "warning: an unescaped backslash at end of string is not portable"
    ));
}

